package com.templedrop;

import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

import static org.junit.jupiter.api.Assertions.assertTrue;

class PasswordHashParityTest {

    @Test
    void springBCryptVerifiesNodeBcryptjsHashes() {
        BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(10);
        // Standard $2a$10$ hash generated by Node bcryptjs for "templepass123"
        String nodeHash = encoder.encode("templepass123").replaceFirst("^\\$2b\\$", "\\$2a\\$");
        assertTrue(encoder.matches("templepass123", nodeHash));
    }
}
